      writeValue(buffer, value.encode());
    }    else if (value is ClayverLastMessageDto) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is ClayverConversationDto) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is ClayverAttachmentDto) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is ClayverMessageDto) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is ClayverAttachmentInputDto) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is ClayverAgentConversationDto) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is ClayverTagDto) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is ClayverBlockStatusDto) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is ClayverBlockStateDto) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    }    else if (value is ClayverCustomerAccountDto) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    }    else if (value is ClayverCustomerProfileDto) {
