///
/// Each call to this method creates a new [EventChannel], so it should
/// not be called multiple times for the same `instanceName`. To deliver
/// events to multiple listeners, call this method once and listen to the
/// returned broadcast stream multiple times instead.
Stream<int> unreadCount( {String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel unreadCountChannel =
      EventChannel('dev.flutter.pigeon.clayver.ClayverEventApi.unreadCount$instanceName', pigeonMethodCodec);
  return unreadCountChannel.receiveBroadcastStream().map((dynamic event) {
    return event as int;
  });
}
    
